package in.ac.rtu.medicare.web;
import in.ac.rtu.medicare.model.*; import in.ac.rtu.medicare.service.AppointmentService; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/app/*") public class AppServlet extends HttpServlet {private final AppointmentService appointments=new AppointmentService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException {try {User u=(User)r.getSession().getAttribute("user");String path=r.getPathInfo();if("/appointments".equals(path)){r.setAttribute("appointments",u.role()==Role.DOCTOR?appointments.schedule(u.id()):appointments.history(u.id()));r.getRequestDispatcher("/WEB-INF/views/appointments.jsp").forward(r,p);return;}r.getRequestDispatcher("/WEB-INF/views/dashboard.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException {try {User u=(User)r.getSession().getAttribute("user");if("/appointments/book".equals(r.getPathInfo()))appointments.book(u.id(),Long.parseLong(r.getParameter("doctorId")),r.getParameter("appointmentAt"),r.getParameter("reason"));else if("/appointments/cancel".equals(r.getPathInfo()))appointments.cancel(u.id(),Long.parseLong(r.getParameter("id")));p.sendRedirect(r.getContextPath()+"/app/appointments");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,p);}}}
